import { writeFile } from "node:fs/promises";
import path from "node:path";
import type { RenderFormat } from "@/lib/media/captions";

// Title-card graphics generated by the Studio for explainer videos. Original
// artwork only: flat colour, system type, no logos, no third-party media, no
// imitation of a publisher's branding. Every frame says what it is - an
// independent fan guide showing illustrative graphics, not gameplay.
//
// One layout per frame shape. 9:16 is its own composition, not the landscape
// frame scaled down: type sizes, line breaks and the caption-safe zone are
// chosen for a phone held upright.

export const CARDS_VERSION = "cards-1";
export const GUIDE_LINE = "LEONIDA FIELD GUIDE - INDEPENDENT FAN GUIDE";
export const NOT_GAMEPLAY_LINE = "ILLUSTRATIVE GRAPHICS - NOT GAMEPLAY";

export interface CardSpec {
  label: string; // small heading, e.g. "RELEASE DATE"
  value: string; // the main statement
  note: string; // one supporting line
}

export const CARD_LIMITS = { label: 30, value: 60, note: 90 };

const FONT = "/System/Library/Fonts/HelveticaNeue.ttc";
/** Average glyph advance of Helvetica Neue as a share of the font size (measured generously). */
const ADVANCE = 0.6;

interface Layout {
  w: number;
  h: number;
  textW: number; // widest a line of card text may be
  strip: { y: number; h: number };
  header: { size: number; guideY: number; noteY: number; stacked: boolean };
  progressY: number;
  labelY: number;
  labelSize: number;
  ruleY: number;
  valueY: number;
  valueMax: number;
  valueMin: number;
  valueLines: number;
  noteSize: number;
  noteLines: number;
  noteGap: number;
  counterSize: number;
  /** Nothing from the card may be drawn below this line: captions live there. */
  contentBottom: number;
}

const LAYOUT: Record<RenderFormat, Layout> = {
  "16:9": {
    w: 1920,
    h: 1080,
    textW: 1680,
    strip: { y: 118, h: 64 },
    header: { size: 30, guideY: 136, noteY: 136, stacked: false },
    progressY: 182,
    labelY: 300,
    labelSize: 46,
    ruleY: 372,
    valueY: 440,
    valueMax: 112,
    valueMin: 64,
    valueLines: 2,
    noteSize: 40,
    noteLines: 2,
    noteGap: 56,
    counterSize: 30,
    contentBottom: 870,
  },
  "9:16": {
    w: 1080,
    h: 1920,
    textW: 900,
    strip: { y: 196, h: 118 },
    header: { size: 32, guideY: 212, noteY: 262, stacked: true },
    progressY: 314,
    labelY: 540,
    labelSize: 54,
    ruleY: 626,
    valueY: 700,
    valueMax: 124,
    valueMin: 68,
    valueLines: 2,
    noteSize: 46,
    noteLines: 3,
    noteGap: 70,
    counterSize: 34,
    // Captions sit above the platform's bottom interface zone; see captions.ts.
    contentBottom: 1230,
  },
};

export function wrapText(text: string, maxChars: number): string[] {
  const lines: string[] = [];
  let cur = "";
  for (const word of text.trim().split(/\s+/)) {
    if (cur && cur.length + 1 + word.length > maxChars) {
      lines.push(cur);
      cur = word;
    } else cur = cur ? `${cur} ${word}` : word;
  }
  if (cur) lines.push(cur);
  return lines;
}

const charsAt = (width: number, size: number) => Math.max(4, Math.floor(width / (size * ADVANCE)));

interface Fit {
  size: number;
  lines: string[];
  lineH: number;
  noteLines: string[];
  noteY: number;
  counterY: number;
}

/**
 * Largest statement size at which the whole card (statement, note, counter)
 * fits its line limits and stays above the caption area. Null if none does.
 */
function fitCard(card: CardSpec, l: Layout): Fit | null {
  const noteLines = card.note.trim() ? wrapText(card.note, charsAt(l.textW, l.noteSize)) : [];
  if (noteLines.length > l.noteLines) return null;
  for (let size = l.valueMax; size >= l.valueMin; size -= 4) {
    const max = charsAt(l.textW, size);
    const lines = wrapText(card.value, max);
    if (lines.length > l.valueLines || lines.some((x) => x.length > max)) continue;
    const lineH = Math.round(size * 1.16);
    const noteY = l.valueY + lines.length * lineH + l.noteGap;
    const counterY = noteY + noteLines.length * Math.round(l.noteSize * 1.25) + 34;
    if (counterY + l.counterSize <= l.contentBottom) {
      return { size, lines, lineH, noteLines, noteY, counterY };
    }
  }
  return null;
}

/** Problems that would make a card unreadable or overflow; empty when it is fine. */
export function cardProblems(card: CardSpec, index: number): string[] {
  const out: string[] = [];
  const n = index + 1;
  for (const k of ["label", "value", "note"] as const) {
    if (card[k].length > CARD_LIMITS[k]) {
      out.push(`Card ${n}: ${k} is ${card[k].length} characters; the limit is ${CARD_LIMITS[k]}`);
    }
  }
  if (!card.value.trim()) out.push(`Card ${n}: the main statement is empty`);
  if (out.length === 0) {
    for (const format of ["16:9", "9:16"] as const) {
      if (!fitCard(card, LAYOUT[format])) {
        out.push(`Card ${n}: the text does not fit the ${format} layout; shorten it`);
      }
    }
  }
  return out;
}

export interface CardsPlan {
  format: RenderFormat;
  cards: CardSpec[];
  /** Second at which each card appears (card i runs until card i+1 starts). */
  startsSec: number[];
  durationSec: number;
}

/** Pixel region where each card's main statement is drawn (used by visual QA). */
export function valueBand(format: RenderFormat): { x: number; y: number; w: number; h: number } {
  const l = LAYOUT[format];
  return {
    x: (l.w - l.textW) / 2,
    y: l.valueY - 10,
    w: l.textW,
    h: Math.round(l.valueMax * 1.2 * l.valueLines),
  };
}

export const cardWindow = (plan: CardsPlan, i: number): [number, number] => [
  plan.startsSec[i]!,
  i + 1 < plan.startsSec.length ? plan.startsSec[i + 1]! : plan.durationSec,
];

/**
 * Writes the text files the graph needs into `dir` and returns an ffmpeg
 * filter graph that ends in the label [cards]. Text goes through `textfile=`,
 * never into the graph string, so script text cannot alter the filter.
 */
export async function buildCardsGraph(dir: string, plan: CardsPlan): Promise<string> {
  const l = LAYOUT[plan.format];
  if (plan.cards.length === 0 || plan.cards.length !== plan.startsSec.length) {
    throw new Error("Cards and their start times do not match");
  }
  let n = 0;
  const textFile = async (text: string) => {
    const name = `card_${n++}.txt`;
    await writeFile(path.join(dir, name), text);
    return name;
  };
  const draw = async (
    text: string,
    o: { size: number; color: string; x: string; y: number; enable?: string },
  ) =>
    `drawtext=fontfile=${FONT}:textfile=${await textFile(text)}:fontcolor=${o.color}:fontsize=${o.size}:x=${o.x}:y=${o.y}` +
    (o.enable ? `:enable='${o.enable}'` : "");
  const centred = "(w-tw)/2";

  const ops: string[] = [
    `drawbox=x=0:y=${l.strip.y}:w=${l.w}:h=${l.strip.h}:color=0x000000@0.45:t=fill`,
    await draw(GUIDE_LINE, {
      size: l.header.size,
      color: "0xffffff",
      x: l.header.stacked ? centred : "60",
      y: l.header.guideY,
    }),
    await draw(NOT_GAMEPLAY_LINE, {
      size: l.header.size,
      color: "0xffd166",
      x: l.header.stacked ? centred : "w-tw-60",
      y: l.header.noteY,
    }),
    // Progress line: a quiet cue of how far through the video the viewer is.
    `drawbox=x=0:y=${l.progressY}:w='${l.w}*t/${plan.durationSec.toFixed(3)}':h=6:color=0xffd166@0.9:t=fill`,
  ];

  for (let i = 0; i < plan.cards.length; i++) {
    const card = plan.cards[i]!;
    const [a, b] = cardWindow(plan, i);
    const enable = `between(t\\,${a.toFixed(3)}\\,${b.toFixed(3)})`;
    const fit = fitCard(card, l);
    if (!fit) throw new Error(`Card ${i + 1} does not fit the ${plan.format} layout`);
    if (card.label.trim()) {
      ops.push(
        await draw(card.label, {
          size: l.labelSize,
          color: "0xffd166",
          x: centred,
          y: l.labelY,
          enable,
        }),
        `drawbox=x=${l.w / 2 - 100}:y=${l.ruleY}:w=200:h=5:color=0xffd166:t=fill:enable='${enable}'`,
      );
    }
    // The statement eases in from the right over 0.4 s at each card change.
    const slide = `${centred}+max(0\\,(${a.toFixed(3)}+0.4-t)*900)`;
    for (const [k, line] of fit.lines.entries()) {
      ops.push(
        await draw(line, {
          size: fit.size,
          color: "0xffffff",
          x: `'${slide}'`,
          y: l.valueY + k * fit.lineH,
          enable,
        }),
      );
    }
    for (const [k, line] of fit.noteLines.entries()) {
      ops.push(
        await draw(line, {
          size: l.noteSize,
          color: "0xcfd8e3",
          x: centred,
          y: fit.noteY + k * Math.round(l.noteSize * 1.25),
          enable,
        }),
      );
    }
    ops.push(
      await draw(`${i + 1} / ${plan.cards.length}`, {
        size: l.counterSize,
        color: "0x8aa0b6",
        x: centred,
        y: fit.counterY,
        enable,
      }),
    );
  }

  const bg =
    `gradients=size=${l.w}x${l.h}:rate=30:c0=0x0a1626:c1=0x12384a:c2=0x1a2440:c3=0x0d2a3a:` +
    `nb_colors=4:speed=0.02:duration=${plan.durationSec.toFixed(3)}[cardsbg]`;
  return `${bg};[cardsbg]${ops.join(",")},format=yuv420p[cards]`;
}
